def is_power_of_five(x):
    if x <= 0:
        return False
    while x % 5 == 0:
        x //= 5
    return x == 1

results = {}
for n in range(3, 16):
    value = (2**n) - 3
    is_power = is_power_of_five(value)
    results[n] = {
        'value': value,
        'is_power_of_five': is_power
    }

print("Results for n=3 to n=15:")
for n, data in results.items():
    print(f"n={n}: 2^n - 3 = {data['value']}. Is a power of 5: {data['is_power_of_five']}")

